@Service
public class BookingWorkflowService {
    private final BookingOperationsService ops;private final JdbcTemplate db;private final ObjectMapper json;
    public BookingWorkflowService(BookingOperationsService ops,JdbcTemplate db,ObjectMapper json){this.ops=ops;this.db=db;this.json=json;}
    private Map<String,Object> row(long id,boolean lock){var rows=db.queryForList("SELECT * FROM bookings WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Không tìm thấy đơn đặt dịch vụ.");return rows.getFirst();}
    private void owned(Map<String,Object> actor,Map<String,Object> booking){long user=ServiceHttpClient.userId(actor);if("ADMIN".equals(actor.get("role"))||"CUSTOMER".equals(actor.get("role"))&&((Number)booking.get("customer_id")).longValue()==user)return;if("STAFF".equals(actor.get("role"))&&Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM booking_assignments WHERE booking_id=? AND staff_id=? AND (status IN ('ACCEPTED','COMPLETED') OR (status='CANCELLED' AND accepted_at IS NOT NULL)))",Boolean.class,booking.get("id"),user)))return;throw error(HttpStatus.NOT_FOUND,"Không tìm thấy đơn thuộc tài khoản của bạn.");}
    Map<String,Object> bookingView(Map<String,Object> b){
        var service=ops.object(b.get("service_snapshot"));var address=ops.object(b.get("address_snapshot"));var result=new LinkedHashMap<String,Object>();
        result.put("serverNow",Instant.now().toString());result.put("staffResponseDeadline",instant(b.get("staff_response_deadline")));result.put("staffWaitState",b.get("staff_wait_state"));result.put("staffWaitRound",b.get("staff_wait_round"));result.put("quoteId",b.get("quote_id"));result.put("pricingConfirmed",b.get("pricing_confirmed"));result.put("id",b.get("id"));result.put("bookingCode",b.get("booking_code"));result.put("customerId",b.get("customer_id"));result.put("serviceId",b.get("service_id"));result.put("packageId",b.get("package_id"));result.put("addressId",b.get("address_id"));result.put("mode",b.get("booking_mode"));result.put("requiredStaffCount",b.get("required_staff_count"));result.put("startsAt",instant(b.get("starts_at")));result.put("endsAt",instant(b.get("ends_at")));result.put("bookingDate",((Timestamp)b.get("starts_at")).toInstant().atZone(ZONE).toLocalDate().toString());result.put("startTime",((Timestamp)b.get("starts_at")).toInstant().atZone(ZONE).toLocalTime().toString());result.put("endTime",((Timestamp)b.get("ends_at")).toInstant().atZone(ZONE).toLocalTime().toString());result.put("status",b.get("status"));result.put("packagePrice",b.get("base_amount"));result.put("addOnsTotal",b.get("add_on_amount"));result.put("discountAmount",b.get("discount_amount"));result.put("totalAmount",b.get("total_amount"));result.put("promotionCode",b.get("promotion_code"));result.put("paymentMethod",b.get("payment_method"));result.put("paymentStatus",b.get("payment_status"));result.put("notes",b.get("notes"));result.put("createdAt",instant(b.get("created_at")));result.put("updatedAt",instant(b.get("updated_at")));result.put("cancelledAt",instant(b.get("cancelled_at")));result.put("cancellationReason",b.get("cancel_reason"));result.put("cancelledBy",b.get("cancelled_by_type"));result.put("service",service);result.put("address",address);
        result.put("addOns",db.queryForList("SELECT add_on_id AS \"addOnId\",name_snapshot AS \"addOnName\",unit_price AS price,quantity FROM booking_add_ons WHERE booking_id=? ORDER BY id",b.get("id")));
        var assignments=db.queryForList("SELECT id,staff_id AS \"staffId\",status,staff_snapshot AS \"staffSnapshot\",execution_status AS \"executionStatus\",accepted_at AS \"acceptedAt\" FROM booking_assignments WHERE booking_id=? ORDER BY id",b.get("id"));for(var assignment:assignments)if(assignment.containsKey("staffSnapshot"))assignment.put("staffSnapshot",ops.object(assignment.get("staffSnapshot")));result.put("assignments",assignments);result.put("staffId",assignments.stream().filter(a->List.of("ACCEPTED","COMPLETED").contains(a.get("status"))).map(a->a.get("staffId")).findFirst().orElse(null));
        var snapshots=db.queryForList("SELECT staff_snapshot FROM booking_assignments WHERE booking_id=? AND (status IN ('ACCEPTED','COMPLETED') OR EXISTS(SELECT 1 FROM bookings b WHERE b.id=booking_assignments.booking_id AND b.booking_mode='MODE_A')) ORDER BY id DESC LIMIT 1",b.get("id"));if(!snapshots.isEmpty())result.put("staff",ops.object(snapshots.getFirst().get("staff_snapshot")));
        result.put("customServiceData",service.getOrDefault("answers",Map.of()));return result;
    }
    public Map<String,Object> detail(String token,long id){var actor=ops.actor(token,"CUSTOMER","STAFF","ADMIN");var b=row(id,false);owned(actor,b);return bookingView(b);}
    public List<Map<String,Object>> list(String token){var user=ops.actor(token,"CUSTOMER","STAFF","ADMIN");String sql="SELECT * FROM bookings";Object[]args={};if("CUSTOMER".equals(user.get("role"))){sql+=" WHERE customer_id=?";args=new Object[]{user.get("id")};}else if("STAFF".equals(user.get("role"))){sql+=" WHERE id IN(SELECT booking_id FROM booking_assignments WHERE staff_id=? AND (status IN ('ACCEPTED','COMPLETED') OR (status='CANCELLED' AND accepted_at IS NOT NULL)))";args=new Object[]{user.get("id")};}return db.queryForList(sql+" ORDER BY created_at DESC LIMIT 500",args).stream().map(this::bookingView).toList();}
    public List<Map<String,Object>> history(String token,long id){detail(token,id);return db.queryForList("SELECT id,new_status AS status,reason AS description,changed_at AS timestamp,changed_by_type AS \"changedBy\" FROM booking_status_histories WHERE booking_id=? ORDER BY changed_at,id",id);}
    List<String> eligibility(long staff,Map<String,Object> b,Map<String,Object> profile){
        if(!ops.weekRegistered(staff,((Timestamp)b.get("starts_at")).toInstant()))return List.of("SCHEDULE_REQUIRED");
        List<String> reasons=new ArrayList<>();if("MODE_A".equals(b.get("booking_mode")) && (!"WAITING".equals(b.get("staff_wait_state")) || b.get("staff_response_deadline")==null || !((Timestamp)b.get("staff_response_deadline")).toInstant().isAfter(Instant.now())))reasons.add("INVITATION_EXPIRED");long service=((Number)b.get("service_id")).longValue();Instant start=((Timestamp)b.get("starts_at")).toInstant(),end=((Timestamp)b.get("ends_at")).toInstant();var location=ops.object(b.get("address_snapshot"));String district=BookingOperationsService.location(location),city=city(Objects.toString(location.getOrDefault("city",location.get("province")),""));
        if(profile==null)reasons.add("INACTIVE");else{if(!Boolean.TRUE.equals(profile.get("isOnline")))reasons.add("OFFLINE");if(!"AVAILABLE".equals(profile.getOrDefault("staffStatus",profile.get("status"))))reasons.add("INACTIVE");}
        if(start.isBefore(Instant.now()))reasons.add("PAST_START");
        if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM staff_service_capabilities WHERE staff_id=? AND service_id=? AND status='APPROVED' AND approved_at<=now() AND (valid_from IS NULL OR valid_from<=?) AND (valid_until IS NULL OR valid_until>=?))",Boolean.class,staff,service,Timestamp.from(start),Timestamp.from(end))))reasons.add("CAPABILITY_MISSING");
        if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM staff_restrictions WHERE staff_id=? AND status='ACTIVE' AND restriction_type IN ('SERVICE_LIMIT','SUSPENSION') AND (service_id IS NULL OR service_id=?) AND starts_at<? AND (ends_at IS NULL OR ends_at>?))",Boolean.class,staff,service,Timestamp.from(end),Timestamp.from(start))))reasons.add("RESTRICTION");
        if(db.queryForList("SELECT province FROM staff_areas WHERE staff_id=? AND status='ACTIVE' AND COALESCE(NULLIF(ward,''),district)=?",String.class,staff,district).stream().noneMatch(province->city(province).equals(city)))reasons.add("AREA_OUTSIDE");
        if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM staff_availabilities WHERE staff_id=? AND status='AVAILABLE' AND (available_date=? OR (available_date IS NULL AND day_of_week=?)) AND start_time<=? AND end_time>=?)",Boolean.class,staff,java.sql.Date.valueOf(start.atZone(ZONE).toLocalDate()),start.atZone(ZONE).getDayOfWeek().getValue()%7,java.sql.Time.valueOf(start.atZone(ZONE).toLocalTime()),java.sql.Time.valueOf(end.atZone(ZONE).toLocalTime()))))reasons.add("OUTSIDE_AVAILABILITY");
        if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM bookings b JOIN booking_assignments a ON a.booking_id=b.id WHERE a.staff_id=? AND a.status IN ('ASSIGNED','ACCEPTED','COMPLETED') AND b.id<>? AND b.status NOT IN ('CANCELLED','REFUNDED','REJECTED') AND b.starts_at<? AND b.ends_at>?)",Boolean.class,staff,b.get("id"),Timestamp.from(end.plusSeconds(3600)),Timestamp.from(start.minusSeconds(3600)))))reasons.add("BOOKING_CONFLICT");
        long required=((Number)b.get("required_staff_count")).longValue(),count=db.queryForObject("SELECT count(*) FROM booking_assignments WHERE booking_id=? AND status IN ('ACCEPTED','COMPLETED')",Long.class,b.get("id"));if(count>=required)reasons.add("POSITION_FULL");
        if("MODE_A".equals(b.get("booking_mode"))&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM booking_assignments WHERE booking_id=? AND staff_id=? AND status='ASSIGNED')",Boolean.class,b.get("id"),staff)))reasons.add("NOT_INVITED");return reasons;
    }
    private static final Map<String,String> REASONS=Map.ofEntries(Map.entry("INVITATION_EXPIRED","Hết thời gian nhận đơn. Vui lòng chú ý lời mời để có doanh thu tốt hơn."),Map.entry("SCHEDULE_REQUIRED","Bạn cần đăng ký đầy đủ lịch làm việc trong tuần trước khi được xét nhận đơn."),Map.entry("INACTIVE","Tài khoản hoặc trạng thái làm việc không phù hợp."),Map.entry("OFFLINE","Bạn đang ngoại tuyến."),Map.entry("PAST_START","Ca đã qua giờ bắt đầu."),Map.entry("CAPABILITY_MISSING","Chưa có năng lực được Admin xác nhận."),Map.entry("RESTRICTION","Bạn đang bị hạn chế nhận dịch vụ này."),Map.entry("AREA_OUTSIDE","Ca nằm ngoài khu vực hoạt động."),Map.entry("OUTSIDE_AVAILABILITY","Ca nằm ngoài lịch rảnh đã lưu."),Map.entry("BOOKING_CONFLICT","Trùng ca hoặc không đủ khoảng đệm 1 giờ."),Map.entry("POSITION_FULL","Đã đủ nhân viên nhận ca."),Map.entry("NOT_INVITED","Bạn không được mời vào ca Mode A."));
    Map<String,Object> matchItem(long staff,Map<String,Object>b,Map<String,Object>profile){var service=ops.object(b.get("service_snapshot"));var address=ops.object(b.get("address_snapshot"));long occupied=db.queryForObject("SELECT count(*) FROM booking_assignments WHERE booking_id=? AND status IN ('ACCEPTED','COMPLETED')",Long.class,b.get("id"));long required=((Number)b.get("required_staff_count")).longValue();var opportunity=new LinkedHashMap<String,Object>();opportunity.put("id",b.get("id"));opportunity.put("staffResponseDeadline",instant(b.get("staff_response_deadline")));opportunity.put("bookingCode",b.get("booking_code"));opportunity.put("serviceId",b.get("service_id"));opportunity.put("serviceName",Objects.toString(service.get("name"),Objects.toString(service.get("serviceName"),"")));opportunity.put("district",BookingOperationsService.location(address));opportunity.put("startsAt",instant(b.get("starts_at")));opportunity.put("endsAt",instant(b.get("ends_at")));opportunity.put("packageTitle",Objects.toString(service.get("packageName"),""));opportunity.put("netIncome",0);opportunity.put("incomePendingPolicy",true);opportunity.put("mode","MODE_A".equals(b.get("booking_mode"))?"A":"B");opportunity.put("positionsRequired",required);opportunity.put("positionsRemaining",Math.max(0,required-occupied));opportunity.put("requiredCapabilities",List.of());if("MODE_A".equals(b.get("booking_mode")))opportunity.put("invitedStaffId",staff);StaffJobPresentation.summary(opportunity,b,service,address);var reasons=eligibility(staff,b,profile);return Map.of("opportunity",opportunity,"eligibility",Map.of("allowed",reasons.isEmpty(),"reasons",reasons.stream().map(r->Map.of("code",r,"message",REASONS.get(r))).toList(),"checks",List.of()));}
    public Map<String,Object> matching(String token){var user=ops.actor(token,"STAFF");long staff=ServiceHttpClient.userId(user);var profile=ops.identityClient().get("/api/v1/identity/auth/profile",token);var candidates=db.queryForList("SELECT * FROM bookings b WHERE b.pricing_confirmed=true AND b.status IN ('PENDING','MATCHING','STAFF_ASSIGNED') AND b.starts_at>now() AND (b.booking_mode<>'MODE_A' OR (b.staff_wait_state='WAITING' AND b.staff_response_deadline>now())) AND (b.booking_mode='MODE_B' OR EXISTS(SELECT 1 FROM booking_assignments a WHERE a.booking_id=b.id AND a.staff_id=? AND a.status='ASSIGNED')) AND NOT EXISTS(SELECT 1 FROM booking_assignments mine WHERE mine.booking_id=b.id AND mine.staff_id=? AND mine.status IN ('ACCEPTED','COMPLETED','REJECTED')) ORDER BY b.starts_at",staff,staff);return Map.of("items",candidates.stream().map(b->matchItem(staff,b,profile)).toList(),"checkedAt",Instant.now().toString(),"revision",0);}
    @SuppressWarnings("unchecked")
    public Map<String,Object> opportunityDetail(String token,long id) {
        long staff=ServiceHttpClient.userId(ops.actor(token,"STAFF"));
        var b=row(id,false);
        if(!Boolean.TRUE.equals(b.get("pricing_confirmed"))||!List.of("PENDING","MATCHING","STAFF_ASSIGNED").contains(b.get("status")))throw error(HttpStatus.CONFLICT,"Ca không còn mở để nhận. Vui lòng tải lại danh sách.");
        if("MODE_A".equals(b.get("booking_mode"))&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM booking_assignments WHERE booking_id=? AND staff_id=? AND status='ASSIGNED')",Boolean.class,id,staff)))throw error(HttpStatus.NOT_FOUND,"Lời mời này không dành cho bạn.");
        var profile=ops.identityClient().get("/api/v1/identity/auth/profile",token);
        var match=matchItem(staff,b,profile);
        var eligibility=(Map<String,Object>)match.get("eligibility");
        if(!Boolean.TRUE.equals(eligibility.get("allowed")))throw error(HttpStatus.CONFLICT,"Ca hiện không đáp ứng điều kiện nhận việc. Vui lòng tải lại danh sách hoặc kiểm tra lịch làm.");
        var value=new LinkedHashMap<>((Map<String,Object>)match.get("opportunity"));
        StaffJobPresentation.add(value,b,ops.object(b.get("service_snapshot")),ops.object(b.get("address_snapshot")));
        value.put("address",StaffJobPresentation.address(ops.object(b.get("address_snapshot"))));
        value.put("notes",b.get("notes"));
        return value;
    }
    Map<String,Object> assignmentView(long staff,Map<String,Object>b){var assignments=db.queryForList("SELECT * FROM booking_assignments WHERE staff_id=? AND booking_id=? AND (status IN ('ACCEPTED','COMPLETED') OR (status='CANCELLED' AND (accepted_at IS NOT NULL OR cancellation_reason='Hết thời gian nhận đơn'))) ORDER BY id DESC LIMIT 1",staff,b.get("id"));if(assignments.isEmpty())throw error(HttpStatus.NOT_FOUND,"Chưa có ca được nhận.");var a=assignments.getFirst();var service=ops.object(b.get("service_snapshot"));var address=ops.object(b.get("address_snapshot"));var value=new LinkedHashMap<String,Object>();value.put("id",b.get("id"));value.put("assignmentId",a.get("id"));value.put("bookingCode",b.get("booking_code"));value.put("staffId",staff);value.put("customerId",b.get("customer_id"));value.put("serviceId",b.get("service_id"));value.put("serviceName",Objects.toString(service.get("name"),Objects.toString(service.get("serviceName"),"")));value.put("customerName",Objects.toString(address.get("recipientName"),Objects.toString(address.get("receiverName"),"")));value.put("customerPhone",a.get("accepted_at")==null?"":Objects.toString(address.get("recipientPhone"),Objects.toString(address.get("receiverPhone"),"")));value.put("customerAvatar","");value.put("address",a.get("accepted_at")==null?BookingOperationsService.location(address):StaffJobPresentation.address(address));value.put("district",BookingOperationsService.location(address));value.put("date",((Timestamp)b.get("starts_at")).toInstant().atZone(ZONE).toLocalDate().toString());value.put("timeSlot",((Timestamp)b.get("starts_at")).toInstant().atZone(ZONE).toLocalTime()+" - "+((Timestamp)b.get("ends_at")).toInstant().atZone(ZONE).toLocalTime());value.put("startsAt",instant(b.get("starts_at")));value.put("endsAt",instant(b.get("ends_at")));value.put("packageTitle",Objects.toString(service.get("packageName"),""));value.put("notes",b.get("notes"));value.put("totalCustomerPaid",b.get("total_amount"));value.put("platformFee",0);value.put("netIncome",0);value.put("incomePendingPolicy",!"CANCELLED".equals(a.get("execution_status")));value.put("cancellationReason",a.get("cancellation_reason"));value.put("responseTimedOut","Hết thời gian nhận đơn".equals(a.get("cancellation_reason")));value.put("bookingStatus",b.get("status"));value.put("status",a.get("execution_status"));value.put("checklist",ops.objects(a.get("checklist")));value.put("acceptedAt",instant(a.get("accepted_at")));value.put("completedAt",instant(b.get("completed_at")));var conversation=db.queryForList("SELECT id FROM conversations WHERE booking_id=? AND staff_id=?",Long.class,b.get("id"),staff);value.put("conversationId",conversation.isEmpty()?null:conversation.getFirst());StaffJobPresentation.add(value,b,service,address);return value;}
    public List<Map<String,Object>> assignments(String token){long staff=ServiceHttpClient.userId(ops.actor(token,"STAFF"));return db.queryForList("SELECT * FROM bookings WHERE id IN (SELECT booking_id FROM booking_assignments WHERE staff_id=? AND (status IN ('ACCEPTED','COMPLETED') OR (status='CANCELLED' AND (accepted_at IS NOT NULL OR cancellation_reason='Hết thời gian nhận đơn')))) ORDER BY starts_at DESC",staff).stream().map(b->assignmentView(staff,b)).toList();}
    @Transactional public Map<String,Object> claim(String token,long id){long staff=ServiceHttpClient.userId(ops.actor(token,"STAFF"));ops.lockStaff(staff);var b=row(id,true);if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM booking_assignments WHERE booking_id=? AND staff_id=? AND status IN ('ACCEPTED','COMPLETED'))",Boolean.class,id,staff)))return assignmentView(staff,b);if(!Boolean.TRUE.equals(b.get("pricing_confirmed"))||!List.of("PENDING","MATCHING","STAFF_ASSIGNED").contains(b.get("status")))throw error(HttpStatus.CONFLICT,"Ca không còn nhận được.");var profile=ops.identityClient().get("/api/v1/identity/auth/profile",token);var failures=eligibility(staff,b,profile);if(!failures.isEmpty())throw error(HttpStatus.CONFLICT,failures.stream().map(REASONS::get).reduce((a,c)->a+" "+c).orElse("Ca không phù hợp."));
        if("MODE_A".equals(b.get("booking_mode"))){int accepted=db.update("UPDATE booking_assignments SET status='ACCEPTED',accepted_at=now(),execution_status='ACCEPTED' WHERE booking_id=? AND staff_id=? AND status='ASSIGNED' AND EXISTS(SELECT 1 FROM bookings b WHERE b.id=booking_assignments.booking_id AND b.staff_response_deadline>clock_timestamp())",id,staff);if(accepted!=1)throw error(HttpStatus.CONFLICT,"Hết thời gian nhận đơn. Vui lòng chờ lời mời mới.");}else ops.insert("INSERT INTO booking_assignments(booking_id,staff_id,status,accepted_at,execution_status) VALUES (?,?,'ACCEPTED',now(),'ACCEPTED')",id,staff);
        var definition=ops.object(b.get("service_snapshot"));List<Map<String,Object>>checks=new ArrayList<>();Object rawSteps=definition.get("workflow");if(rawSteps instanceof List<?>steps){for(int i=0;i<steps.size();i++)checks.add(Map.of("id","step-"+i,"title",Objects.toString(steps.get(i),""),"done",false));}db.update("UPDATE booking_assignments SET checklist=CAST(? AS jsonb) WHERE booking_id=? AND staff_id=? AND status='ACCEPTED'",json.writeValueAsString(checks),id,staff);
        Map<String,Object>snapshot=new LinkedHashMap<>();for(String field:List.of("id","fullName","avatar","rating","reviewCount","experienceYears","isVerified"))if(profile.get(field)!=null)snapshot.put(field,profile.get(field));var score=db.queryForMap("SELECT coalesce(avg(rating),5) AS rating,count(*) AS reviews FROM reviews WHERE staff_id=? AND moderation_status IN ('PUBLISHED','RESOLVED')",staff);snapshot.put("rating",score.get("rating"));snapshot.put("reviewCount",score.get("reviews"));db.update("UPDATE booking_assignments SET staff_snapshot=CAST(? AS jsonb) WHERE booking_id=? AND staff_id=? AND status='ACCEPTED'",json.writeValueAsString(snapshot),id,staff);
        db.update("INSERT INTO staff_reservations(staff_id,booking_id,starts_at,ends_at,status) VALUES (?,?,?,?,'CONFIRMED')",staff,id,b.get("starts_at"),Timestamp.from(((Timestamp)b.get("ends_at")).toInstant().plusSeconds(3600)));
        db.update("INSERT INTO conversations(booking_id,customer_id,staff_id) VALUES (?,?,?) ON CONFLICT(booking_id,staff_id) DO NOTHING",id,b.get("customer_id"),staff);
        db.update("UPDATE bookings SET staff_wait_state=CASE WHEN staff_wait_state IS NULL THEN NULL ELSE 'CLOSED' END WHERE id=?",id);
        long filled=db.queryForObject("SELECT count(*) FROM booking_assignments WHERE booking_id=? AND status='ACCEPTED'",Long.class,id);if(filled>=((Number)b.get("required_staff_count")).longValue())transition(b,"CONFIRMED",staff,"STAFF","Đã đủ nhân viên xác nhận ca.");else transition(b,"MATCHING",staff,"STAFF","Nhân viên đã nhận một vị trí, tiếp tục tìm nhân viên.");return assignmentView(staff,row(id,false));
    }
    void transition(Map<String,Object>b,String next,long user,String role,String reason){db.update("UPDATE bookings SET status=?,updated_at=now(),version=version+1 WHERE id=?",next,b.get("id"));ops.insert("INSERT INTO booking_status_histories(booking_id,old_status,new_status,changed_by,changed_by_type,reason) VALUES (?,?,?,?,?,?)",b.get("id"),b.get("status"),next,"SYSTEM".equals(role)?null:user,role,reason);ops.insert("INSERT INTO outbox_events(aggregate_type,aggregate_id,event_type,payload) VALUES ('BOOKING',?,?,CAST(? AS jsonb))",b.get("id"),next,json.writeValueAsString(Map.of("bookingId",b.get("id"),"customerId",b.get("customer_id"),"status",next,"oldStatus",b.get("status"),"reason",reason)));}
    @Transactional public Map<String,Object> progress(String token,long id,Map<String,Object>body){long staff=ServiceHttpClient.userId(ops.actor(token,"STAFF"));ops.lockStaff(staff);var b=row(id,true);owned(Map.of("id",staff,"role","STAFF"),b);var rows=db.queryForList("SELECT * FROM booking_assignments WHERE booking_id=? AND staff_id=? AND status IN ('ACCEPTED','COMPLETED') FOR UPDATE",id,staff);if(rows.isEmpty())throw error(HttpStatus.CONFLICT,"Ca chưa được bạn nhận.");var a=rows.getFirst();String next=text(body,"status",20,true),current=(String)a.get("execution_status");if(next.equals(current))return assignmentView(staff,b);if(List.of("CANCELLED","REFUNDING","REFUNDED").contains(b.get("status")))throw error(HttpStatus.CONFLICT,"Đơn đã kết thúc.");var allowed=Map.of("ACCEPTED",List.of("EN_ROUTE","CANCELLED"),"EN_ROUTE",List.of("IN_PROGRESS","CANCELLED"),"IN_PROGRESS",List.of("COMPLETED","CANCELLED"));if(!allowed.getOrDefault(current,List.of()).contains(next))throw error(HttpStatus.CONFLICT,"Không thể chuyển trạng thái ca từ "+current+" sang "+next+".");
        if(List.of("EN_ROUTE","IN_PROGRESS").contains(next)&&db.queryForObject("SELECT count(*) FROM booking_assignments WHERE booking_id=? AND status IN ('ACCEPTED','COMPLETED')",Long.class,id)<((Number)b.get("required_staff_count")).longValue())throw error(HttpStatus.CONFLICT,"Đơn chưa đủ nhân viên xác nhận. Vui lòng chờ đủ vị trí trước khi thực hiện ca.");if(next.equals("CANCELLED")&&b.get("started_at")!=null)throw error(HttpStatus.CONFLICT,"Ca đã bắt đầu thực hiện. Hãy báo cáo sự cố để Admin xử lý thay vì tự hủy và tìm người thay thế.");
        String assignmentState=next.equals("COMPLETED")?"COMPLETED":next.equals("CANCELLED")?"CANCELLED":"ACCEPTED";db.update("UPDATE booking_assignments SET execution_status=?,status=? WHERE id=?",next,assignmentState,a.get("id"));
        if(next.equals("IN_PROGRESS")){db.update("UPDATE bookings SET started_at=COALESCE(started_at,now()) WHERE id=?",id);transition(b,"IN_PROGRESS",staff,"STAFF","Nhân viên bắt đầu thực hiện dịch vụ.");db.update("UPDATE staff_reservations SET status='IN_PROGRESS' WHERE booking_id=? AND staff_id=? AND status='CONFIRMED'",id,staff);}
        if(next.equals("COMPLETED")){db.update("UPDATE staff_reservations SET status='COMPLETED' WHERE booking_id=? AND staff_id=?",id,staff);long done=db.queryForObject("SELECT count(*) FROM booking_assignments WHERE booking_id=? AND status='COMPLETED'",Long.class,id);if(done>=((Number)b.get("required_staff_count")).longValue()){db.update("UPDATE bookings SET completed_at=now() WHERE id=?",id);transition(b,"COMPLETED",staff,"STAFF","Tất cả nhân viên đã hoàn thành dịch vụ.");db.update("UPDATE conversations SET status='CLOSED',closed_at=now() WHERE booking_id=?",id);}}
        if(next.equals("CANCELLED")){String reason=text(body,"reason",2000,true);db.update("UPDATE staff_reservations SET status='CANCELLED' WHERE booking_id=? AND staff_id=?",id,staff);db.update("UPDATE conversations SET status='CLOSED',closed_at=now() WHERE booking_id=? AND staff_id=?",id,staff);ops.insert("INSERT INTO booking_incidents(booking_id,reporter_id,reporter_role,reason) VALUES (?,?,'STAFF',?)",id,staff,reason);transition(b,"MATCHING",staff,"STAFF","Nhân viên hủy ca: "+reason);}
        return assignmentView(staff,row(id,false));
    }
    @Transactional public Map<String,Object> checklist(String token,long id,Map<String,Object>body){long staff=ServiceHttpClient.userId(ops.actor(token,"STAFF"));var b=row(id,true);owned(Map.of("id",staff,"role","STAFF"),b);if(List.of("COMPLETED","CANCELLED","REFUNDED").contains(b.get("status")))throw error(HttpStatus.CONFLICT,"Ca đã kết thúc.");var rows=db.queryForList("SELECT id,checklist FROM booking_assignments WHERE booking_id=? AND staff_id=? AND status='ACCEPTED'",id,staff);if(rows.isEmpty())throw error(HttpStatus.FORBIDDEN,"Bạn chưa nhận ca này.");var checks=ops.objects(rows.getFirst().get("checklist"));String key=text(body,"id",100,true);boolean found=false;if(body.containsKey("done")&&!(body.get("done") instanceof Boolean))throw error(HttpStatus.BAD_REQUEST,"Trạng thái checklist không hợp lệ.");for(var check:checks)if(key.equals(Objects.toString(check.get("id")))){check.put("done",body.containsKey("done")?body.get("done"):!Boolean.TRUE.equals(check.get("done")));found=true;}if(!found)throw error(HttpStatus.NOT_FOUND,"Không tìm thấy hạng mục.");db.update("UPDATE booking_assignments SET checklist=CAST(? AS jsonb) WHERE id=?",json.writeValueAsString(checks),rows.getFirst().get("id"));return assignmentView(staff,b);}
    @Transactional public Map<String,Object> cancel(String token,long id,Map<String,Object>body){var actor=ops.actor(token,"CUSTOMER","ADMIN");var b=row(id,true);owned(actor,b);if("CANCELLED".equals(b.get("status")))return bookingView(b);if(b.get("started_at")!=null||!List.of("PENDING","MATCHING","CONFIRMED","ACCEPTED","STAFF_ASSIGNED").contains(b.get("status")))throw error(HttpStatus.CONFLICT,"Đơn không còn được hủy ở trạng thái này.");String reason=text(body,"reason",2000,true);db.update("UPDATE bookings SET cancel_reason=?,cancelled_by=?,cancelled_by_type=?,cancelled_at=now() WHERE id=?",reason,actor.get("id"),actor.get("role"),id);db.update("UPDATE bookings SET staff_wait_state=CASE WHEN staff_wait_state IS NULL THEN NULL ELSE 'CLOSED' END WHERE id=?",id);db.update("UPDATE booking_assignments SET status='CANCELLED',execution_status='CANCELLED',cancellation_reason=? WHERE booking_id=? AND status IN ('ASSIGNED','ACCEPTED')",reason,id);db.update("UPDATE staff_reservations SET status='CANCELLED' WHERE booking_id=? AND status IN ('HELD','CONFIRMED')",id);db.update("UPDATE conversations SET status='CLOSED',closed_at=now() WHERE booking_id=?",id);transition(b,"CANCELLED",ServiceHttpClient.userId(actor),(String)actor.get("role"),reason);return bookingView(row(id,false));}
    public List<Map<String,Object>> reviews(String token){var user=ops.actor(token,"STAFF","ADMIN","CUSTOMER");String filter="ADMIN".equals(user.get("role"))?"":"STAFF".equals(user.get("role"))?" WHERE staff_id=? AND moderation_status<>'HIDDEN'":" WHERE customer_id=?";return db.queryForList("SELECT id,booking_id AS \"bookingId\",customer_id AS \"customerId\",staff_id AS \"staffId\",service_id AS \"serviceId\",rating,comment,tags::text AS tags,moderation_status AS status,internal_note AS \"internalNote\",created_at AS \"createdAt\" FROM reviews"+filter+" ORDER BY created_at DESC",filter.isEmpty()?new Object[]{}:new Object[]{user.get("id")}).stream().map(r->{r.put("tags",json.readValue(Objects.toString(r.get("tags"),"[]"),new TypeReference<List<String>>(){}));if(!"ADMIN".equals(user.get("role")))r.remove("internalNote");return r;}).toList();}
    @Transactional public Map<String,Object> moderateReview(String token,long id,Map<String,Object>b){ops.actor(token,"ADMIN");String status=text(b,"status",20,true);if(!List.of("PUBLISHED","HIDDEN","RESOLVED").contains(status))throw error(HttpStatus.BAD_REQUEST,"Trạng thái kiểm duyệt không hợp lệ.");if(db.update("UPDATE reviews SET moderation_status=?,internal_note=?,updated_at=now() WHERE id=?",status,text(b,"internalNote",2000,false),id)==0)throw error(HttpStatus.NOT_FOUND,"Không tìm thấy đánh giá.");return Map.of("id",id,"status",status);}
    @Transactional public Map<String,Object> incident(String token,long id,Map<String,Object>body){var user=ops.actor(token,"STAFF","CUSTOMER","ADMIN");var b=row(id,false);owned(user,b);long issue=ops.insert("INSERT INTO booking_incidents(booking_id,reporter_id,reporter_role,reason) VALUES (?,?,?,?)",id,user.get("id"),user.get("role"),text(body,"reason",2000,true));return Map.of("id",issue,"status","OPEN");}
    @Transactional public Map<String,Object> reject(String token,long id){long staff=ServiceHttpClient.userId(ops.actor(token,"STAFF"));ops.lockStaff(staff);var b=row(id,true);int count=db.update("UPDATE booking_assignments SET status='REJECTED',rejected_at=now() WHERE booking_id=? AND staff_id=? AND status='ASSIGNED'",id,staff);if(count==0)throw error(HttpStatus.CONFLICT,"Không có lời mời đang chờ cho tài khoản của bạn.");transition(b,"NO_STAFF_FOUND",staff,"STAFF","Nhân viên từ chối lời mời.");return Map.of("id",id,"status","REJECTED");}
    @org.springframework.transaction.annotation.Transactional public Map<String,Object> createReview(String token,long id,Map<String,Object>body){var user=ops.actor(token,"CUSTOMER");var b=row(id,true);owned(user,b);if(!"COMPLETED".equals(b.get("status")))throw error(HttpStatus.CONFLICT,"Chỉ được đánh giá sau khi đơn hoàn thành.");long staff=num(body,"staffId",0,1,Long.MAX_VALUE),rating=num(body,"rating",0,1,5);if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM booking_assignments WHERE booking_id=? AND staff_id=? AND status='COMPLETED')",Boolean.class,id,staff)))throw error(HttpStatus.BAD_REQUEST,"Nhân viên không thuộc đơn đã hoàn thành.");String comment=text(body,"comment",2000,false);var normalizedTags=stringList(body.getOrDefault("tags",List.of()));var prior=db.queryForList("SELECT id,rating,comment,tags FROM reviews WHERE booking_id=? AND staff_id=?",id,staff);if(!prior.isEmpty()){var old=prior.getFirst();if(((Number)old.get("rating")).longValue()!=rating||!Objects.toString(old.get("comment"),"").equals(comment)||!json.readValue(old.get("tags").toString(),new TypeReference<List<String>>(){}).equals(normalizedTags))throw error(HttpStatus.CONFLICT,"Đơn đã được đánh giá.");return Map.of("id",old.get("id"));}var tags=normalizedTags;long review=ops.insert("INSERT INTO reviews(booking_id,customer_id,staff_id,service_id,rating,comment,tags) VALUES (?,?,?,?,?,?,CAST(? AS jsonb))",id,user.get("id"),staff,b.get("service_id"),rating,comment,json.writeValueAsString(tags));return Map.of("id",review);}
    public List<Map<String,Object>> publicReviews(long serviceId){return db.queryForList("SELECT id,rating,comment,created_at AS \"createdAt\" FROM reviews WHERE service_id=? AND moderation_status IN ('PUBLISHED','RESOLVED') ORDER BY created_at DESC LIMIT 100",serviceId);}
    public List<Map<String,Object>>publicReviewStats(){return db.queryForList("SELECT service_id AS \"serviceId\",count(*) AS \"reviewCount\",avg(rating) AS rating FROM reviews WHERE moderation_status IN ('PUBLISHED','RESOLVED') GROUP BY service_id");}

}
